// Garbage collector
// =================
//
// The heap is one reserved region cut into 64 KB blocks. A small block holds
// slots of one size class; a large object takes whole blocks. Each block
// starts with a header holding an allocation and a mark bitmap. Every word
// of a live object, of a thread's stack and of the registered roots is read
// as a possible pointer; pointers into the middle of an object keep it too.
// A thread allocates from a private free list; the block behind that list
// is not swept until the thread moves on to another one.

#define GC_BLK_SHIFT 16
#define GC_BLK ((uintptr_t)1 << GC_BLK_SHIFT)
#define GC_MAXBLK ((uintptr_t)1 << 22)
#define GC_HDR 64
#define GC_SMALL 256
#define GC_NCLS 31
#define GC_MAXTHR 256
#define GC_SIG SIGUSR2

typedef struct GcBlk {
  uint32_t words;    // slot size (small) or object size (large), in words
  uint32_t nobj;     // slots in the block (1 for a large object)
  uint32_t nblk;     // blocks spanned
  uint8_t atomic;    // holds no pointers: never scanned
  uint8_t large;
  uint8_t owned;     // in a thread's cache: not swept
  uint8_t cls;
  struct GcBlk *next;
} GcBlk;

// What matches and the collector read most, by block index, in dense tables
// (a block's own header is a page away from most of its objects): a block's
// allocation and mark bits (gc_abits, gc_mbits: 64 words a block), and:
typedef struct GcMeta {
  uint32_t recip;    // 2^32 / slot bytes, rounded up: a slot's index by multiplying
  uint8_t large, pad[3];
} GcMeta;
_Static_assert(sizeof(GcBlk) <= GC_HDR, "GC_HDR holds a block header");

// A thread's allocation cache for one size class: a fresh block is handed out
// by bumping; a partly free one by the free bits of its bitmap, a word at a
// time (the slots are not touched until they are handed out).
typedef struct GcCache {
  V *bump; V *end; GcBlk *blk; V *objs;
  uint8_t reuse;    // the block came from the reuse queue: its slots are not new memory
  uint64_t bits;    // free slots of word j
  uint32_t idx, j, nj;
} GcCache;

struct PDeque;

// Classes of up to 16 words (nodes) reuse the slots matches free.
#define GC_RQCLS 15

typedef struct Thr {
  GcCache cache[2][GC_NCLS];
  uint32_t rcur[GC_RQCLS];  // where the next search for a reuse block starts
  uintptr_t top;
  volatile uintptr_t sp;
  pthread_t id;
  volatile int live;
  struct PDeque *dq;
  uint32_t rng;
} Thr;

typedef struct { V *p; size_t n; } GcRange;
typedef struct { uint32_t at, len; } GcRun;

extern const uint16_t gc_cls_w[GC_NCLS];
