// Natives: Nat (unbounded)
// ------------------------

#define NAT_BIG ((V)1 << 63)
static inline V *nat_p(V x) { return (V *)(uintptr_t)(x & ~NAT_BIG); }

// The limbs of x (little-endian); a small x is written to *buf.
static inline const V *nat_limbs(V x, V *buf, size_t *n) {
  if (x >> 63) { V *p = nat_p(x); *n = (size_t)p[0]; return p + 1; }
  *buf = x;
  *n = x ? 1 : 0;
  return buf;
}

// A Nat from n limbs (normalized; small when it fits).
V nat_make(const V *d, size_t n);

int nat_cmp3(V a, V b);

V nat_add(V a, V b);

// a - b, or 0 when b >= a.
V nat_sub(V a, V b);

V nat_mul(V a, V b);

// Divides u (m limbs) by v (n >= 2 limbs, m >= n): Knuth's algorithm D.
void nat_divlimbs(const V *u, size_t m, const V *v, size_t n, V *q, V *r);

// (a / b, a % b); dividing by 0 gives (0, a), as Base's Nat.divmod does.
void nat_divmod2(V a, V b, V *qo, V *ro);

V nat_pow(V a, V n);

// Decimal digits of x (malloc'd, NUL-terminated).
char *nat_digits(V x);

static inline V nat_addk(V x, V k) { return LIKELY(!(x >> 63)) && x + k < NAT_BIG ? x + k : nat_add(x, k); }
static inline V nat_subk(V x, V k) { return LIKELY(!(x >> 63)) ? x - k : nat_sub(x, k); }
static inline int nat_ge(V x, V k) { return (x >> 63) || x >= k; }

static inline V F_Nat_ddouble(V a) { return nat_add(a, a); }
static inline V F_Nat_dadd(V a, V b) { return nat_add(a, b); }
static inline V F_Nat_dsub(V a, V b) { return nat_sub(a, b); }
static inline V F_Nat_dmul(V a, V b) { return nat_mul(a, b); }
static inline V F_Nat_ddivmod(V a, V b) { V q, r; nat_divmod2(a, b, &q, &r); return C2(0, q, r); }
static inline V F_Nat_ddiv(V a, V b) { V q, r; nat_divmod2(a, b, &q, &r); return q; }
static inline V F_Nat_dmod(V a, V b) { V q, r; nat_divmod2(a, b, &q, &r); return r; }
static inline V F_Nat_dcmp(V a, V b) { int c = nat_cmp3(a, b); return c < 0 ? IMM(0) : c == 0 ? IMM(1) : IMM(2); }
static inline V F_Nat_dis__eq(V a, V b) { return BOOL(nat_cmp3(a, b) == 0); }
static inline V F_Nat_dis__ne(V a, V b) { return BOOL(nat_cmp3(a, b) != 0); }
static inline V F_Nat_dis__lt(V a, V b) { return BOOL(nat_cmp3(a, b) < 0); }
static inline V F_Nat_dis__le(V a, V b) { return BOOL(nat_cmp3(a, b) <= 0); }
static inline V F_Nat_dis__gt(V a, V b) { return BOOL(nat_cmp3(a, b) > 0); }
static inline V F_Nat_dis__ge(V a, V b) { return BOOL(nat_cmp3(a, b) >= 0); }
static inline V F_Nat_dmin(V a, V b) { return nat_cmp3(a, b) < 0 ? a : b; }
static inline V F_Nat_dmax(V a, V b) { return nat_cmp3(a, b) < 0 ? b : a; }
static inline V F_Nat_dpow(V a, V n) { return nat_pow(a, n); }
V F_Nat_dshow(V a);

// Map.bit(key, pos): bit pos of key as Base's tries read it (char pos / 33;
// offset 0 is "the char exists", offset 1 + b is bit 31 - b of its code),
// with the key handed back. Base rebuilds the key's prefix to hand it back;
// here the key is shared, so a lookup allocates nothing.
#ifdef BEND_NATIVE_MAP_BIT
static inline V F_Map_dbit(V key, V pos) {
  if (pos >> 63) return C2(0, key, IMM(0));
  V ci = pos / 33, off = pos % 33, s = key;
  for (;;) {
    if (s == SNIL) return C2(0, key, IMM(0));
    if (ci == 0) break;
    s = ((V *)s)[2];
    ci--;
  }
  V x = ((V *)s)[1];
  return C2(0, key, off == 0 ? IMM(1) : (((uint32_t)x >> (32 - off)) & 1) ? IMM(1) : IMM(0));
}
#endif

// Natives: U32
// ------------

#define U(x) ((uint32_t)(x))
static inline V nat_low32(V n) { return (n >> 63) ? U(nat_p(n)[1]) : U(n); }
static inline V F_U32_dinc(V a) { return U(a + 1); }
static inline V F_U32_dadd(V a, V b) { return U(a + b); }
static inline V F_U32_dsub(V a, V b) { return U(a - b); }
static inline V F_U32_dmul(V a, V b) { return U(U(a) * U(b)); }
static inline V F_U32_ddiv(V a, V b) { return b == 0 ? 0 : U(a) / U(b); }
static inline V F_U32_dmod(V a, V b) { return b == 0 ? a : U(a) % U(b); }
static inline V F_U32_dnot(V a) { return U(~a); }
static inline V F_U32_dand(V a, V b) { return a & b; }
static inline V F_U32_dor(V a, V b) { return a | b; }
static inline V F_U32_dxor(V a, V b) { return a ^ b; }
static inline V F_U32_dshl(V a) { return U(a << 1); }
static inline V F_U32_dshr(V a) { return a >> 1; }
static inline V F_U32_dshln(V a, V n) { return n >= 32 ? 0 : U(a << n); }
static inline V F_U32_dshrn(V a, V n) { return n >= 32 ? 0 : a >> n; }
static inline V F_U32_dcmp(V a, V b) { return a < b ? IMM(0) : a == b ? IMM(1) : IMM(2); }
static inline V F_U32_dis__eq(V a, V b) { return BOOL(a == b); }
static inline V F_U32_dis__ne(V a, V b) { return BOOL(a != b); }
static inline V F_U32_dis__lt(V a, V b) { return BOOL(a < b); }
static inline V F_U32_dis__le(V a, V b) { return BOOL(a <= b); }
static inline V F_U32_dis__gt(V a, V b) { return BOOL(a > b); }
static inline V F_U32_dis__ge(V a, V b) { return BOOL(a >= b); }
static inline V F_U32_dis__zero(V a) { return BOOL(a == 0); }
static inline V F_U32_dis__even(V a) { return BOOL((a & 1) == 0); }
static inline V F_U32_dto__nat(V a) { return a; }
static inline V F_U32_dfrom__nat(V n) { return nat_low32(n); }
static inline V F_U32_dmin(V a, V b) { return a < b ? a : b; }
static inline V F_U32_dmax(V a, V b) { return a < b ? b : a; }
static inline V F_U32_dpow(V a, V n) {
  // a^n mod 2^32; an odd a has an order dividing 2^30, an even one reaches 0.
  V e;
  if (n >> 63) { if (!(a & 1)) return 0; e = nat_p(n)[1] & ((1u << 30) - 1); }
  else e = n;
  uint32_t r = 1, b = U(a);
  for (; e; e >>= 1) { if (e & 1) r *= b; b *= b; }
  return r;
}
static inline V F_U32_dlog2(V n) {
  V d = 0;
  while (n > 1) { d++; n >>= 1; }
  return d;
}

// Natives: F32 (stored as IEEE bits)
