// Parallel calls
// ==============
//
// A parallel let `a b = f(x) g(y)` forks every value but the last as a task
// (a closure applied to a dummy argument), evaluates the last one, then joins
// the tasks in reverse. Each thread owns a Chase-Lev deque: it pushes and
// pops at the bottom, idle threads steal from the top. A task nobody stole
// runs inline at its join, so a fork costs little more than a closure.

#define P_LOCAL 0
#define P_QUEUED 1
#define P_DONE 2

typedef struct PTask { V clo; V res; V state; V depth; } PTask;

// The fork depth of the running code, and the frontier past which a def
// with a sequential clone (S_name, see bendc) runs its parallel lets in
// order: below it, forking costs more than it balances.
extern __thread int par_depth;
extern int par_front;

typedef struct PDeque {
  _Atomic long top;
  _Atomic long bot;
  long mask;
  PTask **buf;
} PDeque;

extern int par_nthreads;
extern _Atomic int par_started;
extern pthread_mutex_t par_mu;
extern pthread_cond_t par_cv;
extern _Atomic int par_sleepers;

PDeque *pdq_new(void);

PTask *pdq_pop(PDeque *d);

PTask *pdq_steal(PDeque *d);

void par_exec(PTask *t);

PTask *par_steal(void);

static inline void cpu_relax(void) {
#if defined(__x86_64__)
  __builtin_ia32_pause();
#elif defined(__aarch64__)
  __asm__ __volatile__("yield");
#endif
}

void *par_worker(void *arg);

void par_hook(void);

void par_start(void);

// Forks clo (a closure taking one dummy argument); returns the task. Only a
// thread whose deque is nearly empty queues it (the oldest tasks, which
// thieves take, are the big ones); otherwise the fork is the closure itself,
// tagged with bit 1, and its join just applies it.
V par_fork(V clo);

// Waits for a forked task and returns its value.
V par_join(V tv);

int cpu_count(void);

// Effects
// =======
//
// An effect def compiles to a request node {cid | n << 24, args..., k}. The
// event loop runs each computation's pure code up to its next request, runs
// the effect's host function, then resumes k with the answer. The host
// functions use the official runtime's names and conventions: see
// EFFECTS.md in the Bend guide. A CID encodes how a constructor is laid out
// here: kind << 16 | tag, where kind 0 is a node, 1 a nullary constructor,
// 2 a single-field single-constructor type (the field itself), and 3 an
// effect (its tag is its row in io_eff_rows).

#ifndef CID_TUPLE
#define CID_TUPLE 0u
#endif
#ifndef CID_DONE
#define CID_DONE 1u
#endif
#ifndef CID_FAIL
#define CID_FAIL 0u
#endif
#ifndef CID_SOME
#define CID_SOME 1u
#endif
#ifndef CID_NONE
#define CID_NONE ((1u << 16) | 0u)
#endif
#ifndef CID_TRUE
#define CID_TRUE ((1u << 16) | 1u)
#endif
#ifndef CID_FALSE
#define CID_FALSE ((1u << 16) | 0u)
#endif
#ifndef CID_UNIT
#define CID_UNIT ((1u << 16) | 0u)
#endif

// A request node for effect cid with n fields (its arguments, then k).
static inline V io_req(u64 cid, int n, const V *xs) { return CN(cid | ((V)n << 24), n, xs); }

typedef struct { int unused; } Env;
typedef pthread_mutex_t lock;
#define OUTLINE __attribute__((noinline))
#define IO_READ 1
#define IO_TIME 2
#define IO_HELP 64
extern V io_hole_cell;
