#define io_hand(v) ((Term)(v))
#define io_hand_v(t) ((u64)(t))
#define CID_KIND(c) ((u32)(c) >> 16)
#define CID_TAG(c) ((u32)(c) & 0xffff)

__attribute__((noreturn)) void err_fail(const char *msg);

static inline Term term_pak(u64 cid, Term v) {
  switch (CID_KIND(cid)) {
    case 1: return IMM(CID_TAG(cid));
    case 2: return v;
    default: return C1(CID_TAG(cid), v);
  }
}

// The CID of a constructor value (a node's or a nullary one's).
static inline u64 term_aux(Term t) { return (t & 1) ? ((1u << 16) | (u32)(t >> 3)) : ((V *)t)[0] & ~BEND_SH_BITS; }
